(6794340, 1020188, 89065, '<td valign="top">I love this shot, but I couldn''t consider a waterfall mundane, ever.<br/>Beautiful!</td>', 'I love this shot, but I couldn''t consider a waterfall mundane, ever.Beautiful!', '2012-06-13 14:42:47.000000', NULL, 1),
(6794341, 1020396, 89065, '<td valign="top">Beautiful shot, but not very mundane, so had to vote it lower.</td>', 'Beautiful shot, but not very mundane, so had to vote it lower.', '2012-06-13 14:45:34.000000', NULL, 1),
(6794353, 1020907, 144178, '<td valign="top">Nice detail in your Macro!</td>', 'Nice detail in your Macro!', '2012-06-13 14:58:33.000000', NULL, 1),
(6794366, 1020396, 93171, '<td valign="top">This had the potential to be a stunning photo.  I''m rating it as a 6 because I still like it, but next time, if I were you, I would try to uncenter things a little more.  I would include a little bit more of the sky and shift the camera to the right so that the sun is more to the left of the frame.  Still, very pretty. :)</td>', 'This had the potential to be a stunning photo.  I''m rating it as a 6 because I still like it, but next time, if I were you, I would try to uncenter things a little more.  I would include a little bit more of the sky and shift the camera to the right so that the sun is more to the left of the frame.  Still, very pretty. :)', '2012-06-13 15:06:18.000000', NULL, 1),
(6794367, 1020381, 93171, '<td valign="top">Is this tough mudder?</td>', 'Is this tough mudder?', '2012-06-13 15:06:52.000000', NULL, 1),
