(6798051, 1020744, 142473, '<td valign="top">From the thumb I didn''t think I''d like this.  But I do, and I cannot exactly say why.  I think it has something to do with the good focus on the front of the ship sails, and the contrasting color to the nondescript background.  Though I would argue that the back end of the bottle could be cropped off, so it would not demand so much eye attention and take away from the left half of the image...</td>', 'From the thumb I didn''t think I''d like this.  But I do, and I cannot exactly say why.  I think it has something to do with the good focus on the front of the ship sails, and the contrasting color to the nondescript background.  Though I would argue that the back end of the bottle could be cropped off, so it would not demand so much eye attention and take away from the left half of the image...', '2012-06-19 14:32:22.000000', NULL, 1),
(6798057, 1020896, 114225, '<td valign="top">Interesting take on the challenge. Is the texture due to a screen?</td>', 'Interesting take on the challenge. Is the texture due to a screen?', '2012-06-19 14:42:28.000000', NULL, 1),
(6798059, 1020187, 114225, '<td valign="top">This one I''m not sure what I''m looking at, but it''s neat.</td>', 'This one I''m not sure what I''m looking at, but it''s neat.', '2012-06-19 14:43:10.000000', NULL, 1),
(6798061, 1020745, 114225, '<td valign="top">Possibly the first time anyone has taken an interesting photo of a porta potty :)</td>', 'Possibly the first time anyone has taken an interesting photo of a porta potty :)', '2012-06-19 14:43:52.000000', NULL, 1),
(6798065, 1020891, 114225, '<td valign="top">Ha! Nice take on the challenge. That''s a most mundane experience I want to forget.</td>', 'Ha! Nice take on the challenge. That''s a most mundane experience I want to forget.', '2012-06-19 14:45:02.000000', NULL, 1),
(6798066, 1020887, 114225, '<td valign="top">One person''s mundane is another''s extraordinary view. I bet you get a real mix of votes on this.</td>', 'One person''s mundane is another''s extraordinary view. I bet you get a real mix of votes on this.', '2012-06-19 14:45:52.000000', NULL, 1),
(6798075, 1020385, 114225, '<td valign="top">Different angle on the CD shot. Kind of like Apple''s Cover Flow interface. Very neat.</td>', 'Different angle on the CD shot. Kind of like Apple''s Cover Flow interface. Very neat.', '2012-06-19 15:19:35.000000', NULL, 1),
(6798076, 1020791, 114225, '<td valign="top">Funny to see the very different body language of the subjects.</td>', 'Funny to see the very different body language of the subjects.', '2012-06-19 15:21:04.000000', NULL, 1),
(6798077, 1020880, 114225, '<td valign="top">What a cool shadow the has been produced.</td>', 'What a cool shadow the has been produced.', '2012-06-19 15:21:57.000000', NULL, 1),
(6798078, 1020909, 114225, '<td valign="top">I like the basic composition for a basic item.</td>', 'I like the basic composition for a basic item.', '2012-06-19 15:22:45.000000', NULL, 1),
(6798079, 1020822, 114225, '<td valign="top">Good bit of detail here.</td>', 'Good bit of detail here.', '2012-06-19 15:23:42.000000', NULL, 1),
(6798080, 1020838, 114225, '<td valign="top">I really like this. The setting and the tones really make this special.</td>', 'I really like this. The setting and the tones really make this special.', '2012-06-19 15:26:13.000000', NULL, 1),
(6798082, 1020761, 114225, '<td valign="top">To me, this is probably one of the most breathtaking, and least mundane images of the challenge.</td>', 'To me, this is probably one of the most breathtaking, and least mundane images of the challenge.', '2012-06-19 15:42:24.000000', NULL, 1),
(6798083, 1020742, 12611, '<td valign="top">Looks like a movie set in a film noir where something bad goes down, but the big sky is beautiful.</td>', 'Looks like a movie set in a film noir where something bad goes down, but the big sky is beautiful.', '2012-06-19 15:53:07.000000', NULL, 1),
(6798084, 1020883, 12611, '<td valign="top">great shapes and green tones, and the backward sign is a nice inclusion.</td>', 'great shapes and green tones, and the backward sign is a nice inclusion.', '2012-06-19 15:53:37.000000', NULL, 1),
(6798085, 1020192, 12611, '<td valign="top">reminds me of a bohemian Picasso, perhaps the crop a bit tight.</td>', 'reminds me of a bohemian Picasso, perhaps the crop a bit tight.', '2012-06-19 15:55:24.000000', NULL, 1),
(6798086, 1020902, 114225, '<td valign="top">Great pop in the colors, especially the background.</td>', 'Great pop in the colors, especially the background.', '2012-06-19 15:58:15.000000', NULL, 1),
